  constructor(readonly status: number, readonly code: string, message: string) {
    super(message);
  }
}

const MAX_QUANTITY = 10_000;
const MAX_TOTAL_CENTS = 2_147_483_647;

// Returns merged items (duplicates summed), or null if the body is invalid.
function parseItems(body: unknown): { productId: number; quantity: number }[] | null {
  const items = (body as { items?: unknown } | undefined)?.items;
  if (!Array.isArray(items) || items.length === 0 || items.length > 100) return null;
  const merged = new Map<number, number>();
  for (const it of items) {
    const { productId, quantity } = (it ?? {}) as { productId?: unknown; quantity?: unknown };
    if (!Number.isSafeInteger(productId) || (productId as number) < 1 || (productId as number) > MAX_TOTAL_CENTS) return null;
    if (!Number.isSafeInteger(quantity) || (quantity as number) < 1 || (quantity as number) > MAX_QUANTITY) return null;
    const id = productId as number;
    const total = (merged.get(id) ?? 0) + (quantity as number);
    if (total > MAX_QUANTITY) return null;
    merged.set(id, total);
  }
  return [...merged].map(([productId, quantity]) => ({ productId, quantity })).sort((a, b) => a.productId - b.productId);
}

export function createApp''',1)
s=s.replace('''  app.use((err: Error''','''  app.post("/orders", async (req, res) => {
    const items = parseItems(req.body);
    if (!items) {
      return sendError(res, 400, "invalid_request", "items must be a non-empty list of { productId, quantity } with positive integers");
    }
    const userId = res.locals.user.id;

    // 1. Short transaction: reserve stock (check + decrement in one statement, fixed lock order) and
    //    create a pending order. No outside calls while rows are locked.
    let order: { id: number; totalCents: number };
    const client = await pool.connect();
    try {
      await client.query("begin");
      let total = 0;
      const priced: { productId: number; quantity: number; priceCents: number }[] = [];
      for (const { productId, quantity } of items) {
        const { rows } = await client.query(
          "update products set stock = stock - $2 where id = $1 and stock >= $2 returning price_cents",
          [productId, quantity],
        );
        if (rows.length === 0) {
          const { rowCount } = await client.query("select 1 from products where id = $1", [productId]);
          if (rowCount === 0) throw new HttpError(404, "product_not_found", `Product ${productId} not found`);
          throw new HttpError(409, "insufficient_stock", `Not enough stock for product ${productId}`);
        }
        total += rows[0].price_cents * quantity;
        priced.push({ productId, quantity, priceCents: rows[0].price_cents });
      }
      if (total > MAX_TOTAL_CENTS) throw new HttpError(400, "invalid_request", "Order total too large");
      const { rows: [o] } = await client.query(
        "insert into orders (user_id, status, total_cents) values ($1, 'pending', $2) returning id",
        [userId, total],
      );
      for (const p of priced) {
        await client.query(
          "insert into order_items (order_id, product_id, quantity, price_cents) values ($1, $2, $3, $4)",
          [o.id, p.productId, p.quantity, p.priceCents],
        );
      }
      await client.query("commit");
      order = { id: o.id, totalCents: total };
    } catch (err) {
      await client.query("rollback").catch(() => {});
      if (err instanceof HttpError) return sendError(res, err.status, err.code, err.message);
      throw err;
    } finally {
      client.release();
    }

    // 2. Charge outside any transaction; the key comes from our order so retries never double-charge.
    let paymentId: string;
    try {
      ({ paymentId } = await payments.charge({ amountCents: order.totalCents, idempotencyKey: `order-${order.id}` }));
    } catch (err) {
      console.error(err);
      // 3a. Payment failed: give the stock back, only if the order is still pending.
      const c = await pool.connect();
      try {
        await c.query("begin");
        const { rowCount } = await c.query("update orders set status = 'failed' where id = $1 and status = 'pending'", [order.id]);
        if (rowCount === 1) {
          await c.query(
            `update products p set stock = p.stock + oi.quantity
             from order_items oi where oi.order_id = $1 and oi.product_id = p.id`,
            [order.id],
          );
        }
        await c.query("commit");
      } catch (e) {
        await c.query("rollback").catch(() => {});
        console.error(e);
      } finally {
        c.release();
      }
      return sendError(res, 502, "payment_failed", "Payment failed");
    }

    // 3b. Mark paid.
    const { rows: [created] } = await pool.query(
      "update orders set status = 'paid', payment_id = $2 where id = $1 returning id, status, total_cents, payment_id, created_at",
      [order.id, paymentId],
    );
    const { rows: orderItems } = await pool.query(
      "select product_id, quantity, price_cents from order_items where order_id = $1 order by product_id",
      [order.id],
    );
    res.status(201).json({ ...created, items: orderItems });
  });

  app.use((err: Error''',1)
